def wrap_text(text, width):
    if not text:
        return []
    words = text.split()
    lines = []
    cur = []
    cur_len = 0
    for w in words:
        if not cur:
            cur = [w]
            cur_len = len(w)
        elif cur_len + 1 + len(w) <= width:
            cur.append(w)
            cur_len += 1 + len(w)
        else:
            lines.append(' '.join(cur))
            cur = [w]
            cur_len = len(w)
    if cur:
        lines.append(' '.join(cur))
    return lines

def justify_line(words, width):
    if len(words) == 1:
        return words[0].ljust(width)
    total_len = sum(len(w) for w in words)
    total_spaces = width - total_len
    gaps = len(words) - 1
    base, extra = divmod(total_spaces, gaps)
    result = []
    for i, w in enumerate(words[:-1]):
        space_count = base + (1 if i < extra else 0)
        result.append(w + ' ' * space_count)
    result.append(words[-1])
    return ''.join(result)

def wrap_and_count(text, width):
    if not text:
        return 0
    words = text.split()
    lines = 0
    cur_len = -1
    for w in words:
        if cur_len == -1:
            cur_len = len(w)
            lines = 1
        elif cur_len + 1 + len(w) <= width:
            cur_len += 1 + len(w)
        else:
            lines += 1
            cur_len = len(w)
    return lines

def column_layout(items, ncols, width):
    if not items:
        return []
    rows = []
    for i in range(0, len(items), ncols):
        chunk = items[i:i + ncols]
        rows.append(' '.join(item.ljust(width) for item in chunk))
    return rows

def truncate_ellipsis(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    return s[:maxlen - 3] + '...'

def truncate_words_ellipsis(s, maxwords):
    words = s.split()
    if len(words) <= maxwords:
        return ' '.join(words)
    return ' '.join(words[:maxwords]) + '...'

def truncate_middle(s, maxlen):
    if len(s) <= maxlen:
        return s
    remaining = maxlen - 3
    start_len = (remaining + 1) // 2
    end_len = remaining - start_len
    if end_len <= 0:
        return s[:start_len] + '...'
    return s[:start_len] + '...' + s[-end_len:]

def initials_with_periods(name):
    words = name.split()
    return ''.join(w[0].upper() + '.' for w in words)

def abbreviate_name(name):
    words = name.split()
    if len(words) < 2:
        return name
    return words[0][0] + '. ' + ' '.join(words[1:])

def reverse_name(name):
    words = name.split()
    if len(words) <= 1:
        return name
    return words[-1] + ', ' + ' '.join(words[:-1])

def drop_middle_names(name):
    words = name.split()
    if len(words) <= 2:
        return ' '.join(words)
    return words[0] + ' ' + words[-1]

def camel_to_slug(s):
    result = []
    for i, ch in enumerate(s):
        if ch.isupper() and i > 0:
            result.append('-')
        result.append(ch.lower())
    return ''.join(result)

def slug_with_underscore(s):
    s = s.lower()
